/**
 * The card feature table bundled with the bot package (card-features.json, generated by the tools from the card data and
 * scripts), read once, when first needed: the presets' conditional charge reads its gates (levels.ts, conditional-gates.ts).
 * Imported as a module, not read from a disk: the bots run where there is none (the GUI's worker, the phone apps).
 */
import tableFile from "./card-features.json" with { type: "json" };
import { cardFeatureTable, type CardFeatureFile, type CardFeatureTable } from "./card-features";
import { tableGates, type TableGates } from "./conditional-gates";

let table: CardFeatureTable | null = null;
let gates: TableGates | null = null;

/** The bundled card feature table (parsed once per process). */
export function bundledCardTable(): CardFeatureTable {
  return (table ??= cardFeatureTable(tableFile as unknown as CardFeatureFile));
}

/** The gates of the bundled table (conditional.ts CondGates), made once per process. */
export function bundledGates(): TableGates {
  return (gates ??= tableGates(bundledCardTable()));
}
